import { delete_visitType } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deletevisitDialoge: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    deletevisitDialoge: {
      async handler() {
        if (this.deletevisitDialoge == true) {}
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(delete_visitType, {
          input: {
            visit_type_id: this.rowInfo.visit_type_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.delete_visitType);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
